#!/usr/bin/env python3
"""Install NukeFire Client Milestone 1.5a1 Communications Cleanup safely."""
from __future__ import annotations

import base64
import hashlib
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import zlib

MILESTONE = "Milestone 1.5a1 — Communications Cleanup"
BASELINE_HASHES = {'BUILD-MILESTONE.txt': 'f14f3efe4e7d2b5ff4dcfc3468d1ccdd20e6accce3861104120d0e2c1de4b0ba', 'CHANGELOG.md': '28a0097dcb8dcebc1f7179c9e1a1380fe2d34104c9840d5e4d6d354918c39e06', 'renderer/renderer.js': '949c9a052a3b77cf571df4c1f4eb85bea752fcc1dceeb28a977e5b33a00eeb9a', 'src/communications.js': '9b16cdc92a145f470ab63f48000d2eb0aca7e8c20267996485cb6cf86e6f90fb', 'test/communications.test.js': '85013689f495180287c5b6139d3836fdc9237ec0451688471444d981cfabc22f', 'test/communications-panel.test.js': 'ff05d0d8b8e9652084ea2abfc17a215219c5d7a509269bc334c6fece22dafda3'}
TARGET_HASHES = {'BUILD-MILESTONE.txt': '0b7787f6d2e76b737208337a837ea567d98e96ed3493150efca6cb3dc28cab88', 'CHANGELOG.md': 'cebcfe88bf04ecc50c339fcbea7cfecf2c50c402cedeea2abae06c720adc1826', 'renderer/renderer.js': 'bf79f82df51d7c2f6ab7384c55b8899b455a238da3071ea050cc7db98d185a4d', 'src/communications.js': '71d1360c607442294f404f1b6ed2acc23ceb30b4abe181791c15f7fe47cdeda9', 'test/communications.test.js': 'c31dd3e30514c81729bfc58ac842fb08d940c1a2ab159da544c31cb2287608ea', 'test/communications-panel.test.js': '40f7787ae7a7d4f992c90ed95789f72df60c5eeffe8a06f5bc2a595eda204ec7'}
PAYLOAD = ''


def digest(path: Path) -> str | None:
    if not path.is_file():
        return None
    return hashlib.sha256(path.read_bytes()).hexdigest()


def load_payload() -> dict[str, bytes]:
    packed = zlib.decompress(base64.b64decode(PAYLOAD.encode("ascii")))
    data = json.loads(packed.decode("utf-8"))
    return {name: base64.b64decode(content) for name, content in data.items()}


def run_verify(root: Path) -> None:
    result = subprocess.run(["npm", "run", "verify"], cwd=root)
    if result.returncode != 0:
        raise RuntimeError("npm run verify failed")


def main() -> int:
    root = Path.cwd().resolve()
    if not (root / "package.json").is_file() or not (root / "renderer" / "renderer.js").is_file():
        print("Run this installer from the NukeFire client repository beside package.json.", file=sys.stderr)
        return 2

    current = {name: digest(root / name) for name in BASELINE_HASHES}
    if current == TARGET_HASHES:
        print(f"{MILESTONE} is already installed. Running verification...")
        run_verify(root)
        print("Verification passed.")
        return 0

    mismatches = [
        name for name, expected in BASELINE_HASHES.items()
        if current.get(name) != expected
    ]
    if mismatches:
        print("The working tree does not match the verified Milestone 1.5a baseline.", file=sys.stderr)
        print("Unexpected files:", file=sys.stderr)
        for name in mismatches:
            print(f"  {name}", file=sys.stderr)
        print("No files were changed.", file=sys.stderr)
        return 3

    payload = load_payload()
    backup_dir = Path(tempfile.mkdtemp(prefix="nukefire-1.5a1-backup-"))
    try:
        for name in payload:
            source = root / name
            backup = backup_dir / name
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, backup)

        for name, content in payload.items():
            destination = root / name
            destination.parent.mkdir(parents=True, exist_ok=True)
            temporary = destination.with_name(destination.name + ".1.5a1.tmp")
            temporary.write_bytes(content)
            temporary.replace(destination)

        installed = {name: digest(root / name) for name in TARGET_HASHES}
        if installed != TARGET_HASHES:
            raise RuntimeError("installed file hashes did not match the verified target")

        run_verify(root)
    except Exception as error:
        print(f"Installation failed: {error}", file=sys.stderr)
        print("Restoring the Milestone 1.5a files...", file=sys.stderr)
        for name in payload:
            backup = backup_dir / name
            if backup.is_file():
                destination = root / name
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(backup, destination)
        return 4
    finally:
        shutil.rmtree(backup_dir, ignore_errors=True)

    print(f"{MILESTONE} installed successfully.")
    print("ANSI formatting is cleaned and GMCP/text duplicates are suppressed.")
    print("Restart the client, then use Clear Messages once to discard old session entries.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
